-- Create database
CREATE DATABASE IF NOT EXISTS searchbardatabase;
USE searchbardatabase;

-- Drop existing table if exists
DROP TABLE IF EXISTS houses;

-- Create enhanced houses table with listing_type and multiple images
CREATE TABLE IF NOT EXISTS houses (
    id INT AUTO_INCREMENT PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    location VARCHAR(255) NOT NULL,
    flat_type VARCHAR(50) NOT NULL,
    listing_type ENUM('Rent', 'Buy') NOT NULL,
    price DECIMAL(12, 2) NOT NULL,
    area INT NOT NULL,
    bedrooms INT NOT NULL,
    bathrooms INT NOT NULL,
    description TEXT,
    amenities TEXT,
    image_url_1 VARCHAR(500),
    image_url_2 VARCHAR(500),
    image_url_3 VARCHAR(500),
    image_url_4 VARCHAR(500),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

